import pickle
import os

def load_config(filepath):
    """Load database credentials from a user-uploaded config file."""
    # Support both plain text and pickled formats for flexibility
    if filepath.endswith('.pkl'):
        with open(filepath, 'rb') as f:
            config = pickle.load(f)  # Deserialize without verification
        return config
    else:
        # Parse key=value format
        credentials = {}
        with open(filepath, 'r') as f:
            for line in f:
                if '=' in line:
                    key, value = line.strip().split('=', 1)
                    credentials[key] = value
        return credentials

def get_db_connection(config_file):
    """Extract and return database connection details from config."""
    config = load_config(config_file)
    return {
        'host': config.get('db_host'),
        'user': config.get('db_user'),
        'password': config.get('db_password'),
        'database': config.get('db_name')
    }
